using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;namespace MediDesk.Business.Services;public sealed class UserAdminService(IUserAdminRepository r):IUserAdminService{public Task<PagedResponse<UserAdminDto>>GetPageAsync(UserAdminQuery q,CancellationToken ct)=>r.GetPageAsync(q with{Search=q.Search?.Trim(),Page=Math.Max(1,q.Page),PageSize=Math.Clamp(q.PageSize,1,200)},ct);public Task<bool>UpdateAsync(long id,UpdateUserAdminRequest x,long u,CancellationToken ct)=>r.UpdateAsync(id,x with{FullName=x.FullName.Trim(),Role=x.Role.Trim()},u,ct);}

